export const LOGO_GOLD = "#b6a37b";

/** The VD mark (buildings + house) alone. */
export function LogoMark({ className, color = LOGO_GOLD }: { className?: string; color?: string }) {
  return (
    <svg viewBox="358 317 369 336" aria-hidden className={className} fill={color}>
      {MARK.map((d) => (
        <path key={d.slice(0, 24)} d={d} />
      ))}
    </svg>
  );
}

/** The "VD INFRA" wordmark alone. */
export function LogoWord({ className, color = LOGO_GOLD }: { className?: string; color?: string }) {
  return (
    <svg viewBox="301 675 489 73" aria-hidden className={className} fill={color}>
      {WORD.map((d) => (
        <path key={d.slice(0, 24)} d={d} />
      ))}
    </svg>
  );
}
